class Solution {
    public int monotoneIncreasingDigits(int n){
        char[] digits=String.valueOf(n).toCharArray();
        int marker=digits.length;
        for(int i=digits.length-1;i>0;i--)if(digits[i-1]>digits[i]){
            digits[i-1]--;
            marker=i;
        }
        for(int i=marker;i<digits.length;i++)digits[i]='9';
        return Integer.parseInt(new String(digits));
    }
}

code.kotlin:
class Solution {
    fun monotoneIncreasingDigits(n:Int):Int{
        val digits=n.toString().toCharArray();
        var marker=digits.size;
        for(i in digits.lastIndex downTo 1)if(digits[i-1]>digits[i]){
            digits[i-1]--;
            marker=i
        };
        for(i in marker until digits.size)digits[i]='9';
        return String(digits).toInt()
    }
}

